const ticker = String($json.ticker || '').toUpperCase();
return [{
  json: {
    ...$json,
    ticker,
    fmp_api_key: 'fmp_key',
    limit: 40
  }
}];

const rows = $input.all().map(i => i.json);
const meta = $('Prepare FMP Historical Request').item.json;

return [{
  json: {
    ...meta,
    key_metrics: rows,
    key_metrics_count: rows.length
  }
}];

const rows = $input.all().map(i => i.json);
const meta = $('Wrap Key Metrics Response').first().json;

return [{
  json: {
    ...meta,
    ratios: rows,
    ratios_count: rows.length
  }
}];

const rows = $input.all().map(i => i.json);
const meta = $('Wrap Ratios Response').first().json;

return [{
  json: {
    ...meta,
    growth: rows,
    growth_count: rows.length
  }
}];

const meta = $('Wrap Growth Response').first().json;
const ticker = String(meta.ticker || '').toUpperCase();

const toArray = v => Array.isArray(v) ? v : [];

const toNum = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
};

const round2 = v => {
  if (v === null || v === undefined || !Number.isFinite(v)) return null;
  return Math.round(v * 100) / 100;
};

const round4 = v => {
  if (v === null || v === undefined || !Number.isFinite(v)) return null;
  return Math.round(v * 10000) / 10000;
};

const clamp = (v, lo = 0, hi = 100) => Math.max(lo, Math.min(hi, v));

const scoreInverse = (val, min, max) => {
  val = toNum(val);
  if (val === null || val <= 0) return null;
  return round2(clamp(100 - ((val - min) / (max - min)) * 100));
};

const scoreDirect = (val, min, max) => {
  val = toNum(val);
  if (val === null) return null;
  return round2(clamp(((val - min) / (max - min)) * 100));
};

const weightedScore = pairs => {
  const valid = pairs.filter(p => p.score !== null && p.score !== undefined && Number.isFinite(Number(p.score)) && Number.isFinite(Number(p.weight)));
  const totalWeight = valid.reduce((s, p) => s + Number(p.weight), 0);
  if (!valid.length || totalWeight === 0) return null;
  return round2(valid.reduce((s, p) => s + Number(p.score) * Number(p.weight), 0) / totalWeight);
};

const keyMetrics = toArray(meta.key_metrics);
const ratios = toArray(meta.ratios);
const growth = toArray(meta.growth);

const byDate = {};

function ensure(date) {
  if (!date) return null;
  if (!byDate[date]) byDate[date] = {
    fiscal_date: date,
    calendar_year: null,
    period: null,
    ticker,
    company_name: meta.company_name || null,
    ai_subsector: meta.ai_subsector || null,
    source: 'financial_modeling_prep'
  };
  return byDate[date];
}

for (const r of keyMetrics) {
  const date = r.date || r.fiscalDateEnding || r.calendarDate || r.fiscal_date;
  const row = ensure(date);
  if (!row) continue;

  row.calendar_year = r.calendarYear || r.calendar_year || row.calendar_year || null;
  row.period = r.period || row.period || null;

  row.pe_ratio = toNum(r.peRatio) ?? toNum(r.peRatioTTM) ?? row.pe_ratio ?? null;
  row.ev_ebitda = toNum(r.enterpriseValueOverEBITDA) ?? toNum(r.evToEbitda) ?? row.ev_ebitda ?? null;
  row.ev_sales = toNum(r.evToSales) ?? toNum(r.enterpriseValueOverRevenue) ?? row.ev_sales ?? null;
  row.fcf_yield = toNum(r.freeCashFlowYield) ?? row.fcf_yield ?? null;
  row.roe = toNum(r.roe) ?? row.roe ?? null;
  row.roic = toNum(r.roic) ?? row.roic ?? null;
  row.debt_to_equity = toNum(r.debtToEquity) ?? row.debt_to_equity ?? null;
  row.net_debt_to_ebitda = toNum(r.netDebtToEBITDA) ?? row.net_debt_to_ebitda ?? null;
}

for (const r of ratios) {
  const date = r.date || r.fiscalDateEnding || r.calendarDate || r.fiscal_date;
  const row = ensure(date);
  if (!row) continue;

  row.calendar_year = r.calendarYear || r.calendar_year || row.calendar_year || null;
  row.period = r.period || row.period || null;

  row.pe_ratio = toNum(r.priceEarningsRatio) ?? toNum(r.peRatio) ?? row.pe_ratio ?? null;
  row.gross_margin = toNum(r.grossProfitMargin) ?? row.gross_margin ?? null;
  row.operating_margin = toNum(r.operatingProfitMargin) ?? row.operating_margin ?? null;
  row.net_margin = toNum(r.netProfitMargin) ?? row.net_margin ?? null;
  row.roe = toNum(r.returnOnEquity) ?? row.roe ?? null;
  row.roic = toNum(r.returnOnCapitalEmployed) ?? toNum(r.returnOnInvestedCapital) ?? row.roic ?? null;
  row.debt_to_equity = toNum(r.debtEquityRatio) ?? row.debt_to_equity ?? null;
  row.current_ratio = toNum(r.currentRatio) ?? row.current_ratio ?? null;
}

for (const r of growth) {
  const date = r.date || r.fiscalDateEnding || r.calendarDate || r.fiscal_date;
  const row = ensure(date);
  if (!row) continue;

  row.calendar_year = r.calendarYear || r.calendar_year || row.calendar_year || null;
  row.period = r.period || row.period || null;

  row.revenue_growth = toNum(r.revenueGrowth) ?? row.revenue_growth ?? null;
  row.ebitda_growth = toNum(r.ebitgrowth) ?? toNum(r.ebitdaGrowth) ?? row.ebitda_growth ?? null;
  row.fcf_growth = toNum(r.freeCashFlowGrowth) ?? row.fcf_growth ?? null;
  row.eps_growth = toNum(r.epsgrowth) ?? toNum(r.epsGrowth) ?? row.eps_growth ?? null;
}

const rows = [];

for (const row of Object.values(byDate)) {
  const peScore = scoreInverse(row.pe_ratio, 10, 60);
  const evEbitdaScore = scoreInverse(row.ev_ebitda, 5, 35);
  const fcfYieldScore = scoreDirect(row.fcf_yield, 0, 0.08);

  const valuationScore = weightedScore([
    { score: peScore, weight: 0.40 },
    { score: evEbitdaScore, weight: 0.35 },
    { score: fcfYieldScore, weight: 0.25 }
  ]);

  const roeScore = scoreDirect(row.roe, 0, 0.35);
  const roicScore = scoreDirect(row.roic, 0, 0.30);
  const marginScore = scoreDirect(row.operating_margin ?? row.net_margin, 0, 0.35);
  const leverageScore = scoreInverse(row.debt_to_equity, 0, 3);

  const qualityScore = weightedScore([
    { score: roeScore, weight: 0.30 },
    { score: roicScore, weight: 0.35 },
    { score: marginScore, weight: 0.25 },
    { score: leverageScore, weight: 0.10 }
  ]);

  const revenueGrowthScore = scoreDirect(row.revenue_growth, -0.10, 0.40);
  const fcfGrowthScore = scoreDirect(row.fcf_growth, -0.20, 0.50);
  const epsGrowthScore = scoreDirect(row.eps_growth, -0.20, 0.50);

  const growthScore = weightedScore([
    { score: revenueGrowthScore, weight: 0.50 },
    { score: fcfGrowthScore, weight: 0.25 },
    { score: epsGrowthScore, weight: 0.25 }
  ]);

  const fundamentalScore = weightedScore([
    { score: valuationScore, weight: 0.45 },
    { score: qualityScore, weight: 0.35 },
    { score: growthScore, weight: 0.20 }
  ]);

  rows.push({
    fiscal_date: row.fiscal_date,
    calendar_year: row.calendar_year,
    period: row.period,
    ticker: row.ticker,
    company_name: row.company_name,
    ai_subsector: row.ai_subsector,
    pe_ratio: round4(row.pe_ratio),
    ev_ebitda: round4(row.ev_ebitda),
    ev_sales: round4(row.ev_sales),
    fcf_yield: round4(row.fcf_yield),
    revenue_growth: round4(row.revenue_growth),
    ebitda_growth: round4(row.ebitda_growth),
    fcf_growth: round4(row.fcf_growth),
    eps_growth: round4(row.eps_growth),
    gross_margin: round4(row.gross_margin),
    operating_margin: round4(row.operating_margin),
    net_margin: round4(row.net_margin),
    roe: round4(row.roe),
    roic: round4(row.roic),
    debt_to_equity: round4(row.debt_to_equity),
    net_debt_to_ebitda: round4(row.net_debt_to_ebitda),
    current_ratio: round4(row.current_ratio),
    pe_score: peScore,
    ev_ebitda_score: evEbitdaScore,
    fcf_yield_score: fcfYieldScore,
    valuation_score: valuationScore,
    quality_score: qualityScore,
    growth_score: growthScore,
    fundamental_score: fundamentalScore,
    source: 'financial_modeling_prep'
  });
}

rows.sort((a, b) => String(a.fiscal_date || '').localeCompare(String(b.fiscal_date || '')));

return [{
  json: {
    ticker,
    row_count: rows.length,
    rows,
    key_metrics_count: keyMetrics.length,
    ratios_count: ratios.length,
    growth_count: growth.length,
    note: rows.length ? null : 'No historical FMP rows returned'
  }
}];
